void mainImage(out vec4 o, in vec2 f){ vec2 R=iResolution.xy; vec2 uv=f/R; float m=texture(iChannel0,uv).a; 
  float r=length(f-R*vec2(0.5,0.5)); float ring=smoothstep(0.35,0.65,0.5+0.5*sin(r*0.55 - iTime*12.0));
  vec3 col = mix(vec3(0.000,0.851,0.710), vec3(1.0,0.98,0.92), ring);
  o = vec4(col*m, m);
 }

