float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7)))*43758.5453); }
void mainImage(out vec4 o, in vec2 f){ vec2 R=iResolution.xy; vec2 uv=f/R; float m=texture(iChannel0,uv).a; 
  float cs=24.0; vec2 cell=floor(f/cs); vec2 c=(cell+0.5)*cs; float mm=texture(iChannel0,c/R).a;
  float r=length(f-c)/cs; float on=step(0.5,mm);
  float chase = 0.75+0.25*step(0.5,fract((cell.x+cell.y)*0.25 - iTime*4.0));
  float bulb=smoothstep(0.36,0.30,r); float halo=exp(-r*r*7.0);
  vec3 w=vec3(1.000,0.769,0.420);
  vec3 col = on*(w*bulb*1.3*chase + w*halo*0.45) + (1.0-on)*w*0.05*bulb;
  o = vec4(col, max(on*max(bulb,halo*0.8), 1.0*bulb));
 }

