void mainImage(out vec4 o, in vec2 f){ vec2 R=iResolution.xy; vec2 uv=f/R; float m=texture(iChannel0,uv).a; 
  float ang=0.785; mat2 rot=mat2(cos(ang),-sin(ang),sin(ang),cos(ang));
  vec2 q=rot*f; float cs=16.0*(1.0+2.0*exp(-iTime*10.0)); vec2 cc=(floor(q/cs)+0.5)*cs; vec2 back=transpose(rot)*cc;
  float v=textureLod(iChannel0, back/R, 2.5).a;
  float shade = mix(1.0, 0.45, uv.y);
  float rad = sqrt(v*shade)*0.62*cs;
  float d = length(q-cc);
  float dot_ = smoothstep(rad+0.8, rad-0.8, d);
  o = vec4(vec3(0.02)*dot_, dot_);
 }

