void mainImage(out vec4 o, in vec2 f){ vec2 R=iResolution.xy; vec2 uv=f/R; float m=texture(iChannel0,uv).a; 
  float oo=14.0*(1.0+5.0*exp(-iTime*9.0)); float r=texture(iChannel0, uv+vec2(oo,0.0)/R).a, g=m, b=texture(iChannel0, uv-vec2(oo,0.0)/R).a;
  vec3 col=vec3(r, g, b); col = col*vec3(1.0);
