void mainImage(out vec4 o, in vec2 f){ vec2 R=iResolution.xy; vec2 uv=f/R; float m=texture(iChannel0,uv).a; 
  vec3 col=vec3(0.0); float a=0.0;
  for(int k=1;k<15;k++){ float fk=float(k); vec2 off=vec2(-1.0,1.0)*fk*2.0*min(1.0,0.25+iTime*5.0)/R; float s=texture(iChannel0,uv+off).a;
     float hit = step(0.5,s)*(1.0-a); col += hit*mix(vec3(0.878,0.149,0.106), vec3(0.878,0.149,0.106)*0.18, fk/15.0); a=max(a,step(0.5,s)); }
  col = mix(col, vec3(0.961,0.922,0.867), m); a=max(a,m);
  o = vec4(col*a, a);
 }

