void mainImage(out vec4 o, in vec2 f){ vec2 R=iResolution.xy; vec2 uv=f/R; float m=texture(iChannel0,uv).a; 
  float b1=mb(uv,1.0), b3=mb(uv,3.0), b5=mb(uv,5.0);
  float tube=exp(-pow((b1-0.5)/0.16,2.0));
  float core=exp(-pow((b1-0.5)/0.06,2.0));
  float glow=exp(-pow((b3-0.5)/0.32,2.0))*0.55 + exp(-pow((b5-0.45)/0.4,2.0))*0.35;
  float fl = 0.88+0.12*step(0.25,hash(vec2(floor(iTime*24.0),7.0)));
  vec3 c = vec3(0.149,0.878,1.000);
  vec3 col = (c*tube*1.3 + vec3(1.0,0.96,0.92)*core*0.8 + c*glow)*fl*1.0;
  float a = clamp(max(max(tube, core), glow)*1.0, 0.0, 1.0);
  o = vec4(col, a);
 }

