  float cs=9.0; vec2 cell=floor(f/cs); vec2 c=(cell+0.5)*cs; float mm=texture(iChannel0,c/R).a;
  vec2 d=abs(f-c)/cs; float px=step(d.x,0.40)*step(d.y,0.40);
  float sub = fract(f.x/cs*3.0);
